/**
 * Layer 1 / 3b — Null Handling Edge-Case Suite
 * Auto-generated by the autonomous QE framework.
 *
 * Verifies that every nullable field resolves gracefully when the upstream
 * REST stub returns null / undefined / empty array.  No INTERNAL_SERVER_ERROR
 * or unhandled "Cannot read properties of null" should reach the client.
 *
 * Coverage matrix:
 *   - Empty list response        → resolver returns []
 *   - Null single entity         → resolver returns null
 *   - Null nested object         → parent field returns null
 *   - Pagination edge cases      → limit=0, offset>total, limit>dataset
 *   - parse-service null inputs  → parseShip / parseLaunchpad with nullish values
 */

import { ApolloServer } from '@apollo/server';
import { buildSubgraphSchema } from '@apollo/subgraph';
import { readFileSync } from 'fs';
import gql from 'graphql-tag';
import { ApolloServerPluginInlineTraceDisabled } from '@apollo/server/plugin/disabled';
import resolvers from '../../resolvers';
import API from '../../api';

jest.mock('../../api');

const typeDefs = gql(readFileSync('schema.graphql', { encoding: 'utf-8' }));

// ── helpers ───────────────────────────────────────────────────────────────────

let server: ApolloServer;

beforeAll(() => {
  server = new ApolloServer({
    schema: buildSubgraphSchema({ typeDefs, resolvers }),
    plugins: [ApolloServerPluginInlineTraceDisabled()],
  });
});

afterAll(async () => { await server.stop(); });

function singleResult(res: any) {
  return (res.body as any).singleResult;
}

/** Assert no INTERNAL_SERVER_ERROR or null-access crash in the response. */
function assertNoInternalError(res: any) {
  const errors: any[] = singleResult(res)?.errors ?? [];
  const fatal = errors.filter(
    (e) =>
      e.extensions?.code === 'INTERNAL_SERVER_ERROR' ||
      /cannot read prop/i.test(e.message ?? ''),
  );
  expect(fatal).toHaveLength(0);
}

async function exec(query: string, api: jest.Mocked<API>) {
  return server.executeOperation({ query }, { contextValue: { api } });
}

// ── empty list responses ──────────────────────────────────────────────────────

describe('Generated Null Handling: empty list from upstream', () => {
  it('ships → [] when upstream returns []', async () => {
    const api = new API() as jest.Mocked<API>;
    api.getShips.mockResolvedValue([] as any);
    const res = await exec(`{ ships { id name } }`, api);
    assertNoInternalError(res);
    expect(singleResult(res).data?.ships).toEqual([]);
  });

  it('launches → [] when upstream returns []', async () => {
    const api = new API() as jest.Mocked<API>;
    api.getLaunches.mockResolvedValue([] as any);
    const res = await exec(`{ launches { id } }`, api);
    assertNoInternalError(res);
    expect(singleResult(res).data?.launches).toEqual([]);
  });

  it('histories → [] when upstream returns []', async () => {
    const api = new API() as jest.Mocked<API>;
    api.getHistoryEvents.mockResolvedValue([] as any);
    const res = await exec(`{ histories { id title } }`, api);
    assertNoInternalError(res);
    expect(singleResult(res).data?.histories).toEqual([]);
  });

  it('dragons → [] when upstream returns []', async () => {
    const api = new API() as jest.Mocked<API>;
    api.getDragons.mockResolvedValue([] as any);
    const res = await exec(`{ dragons { id name } }`, api);
    assertNoInternalError(res);
    expect(singleResult(res).data?.dragons).toEqual([]);
  });

  it('rockets → [] when upstream returns []', async () => {
    const api = new API() as jest.Mocked<API>;
    api.getRockets.mockResolvedValue([] as any);
    const res = await exec(`{ rockets { id name } }`, api);
    assertNoInternalError(res);
    expect(singleResult(res).data?.rockets).toEqual([]);
  });
});

// ── null single-entity responses ──────────────────────────────────────────────

describe('Generated Null Handling: null single entity from upstream', () => {
  it('ship(id) → null when upstream returns null', async () => {
    const api = new API() as jest.Mocked<API>;
    api.getShip.mockResolvedValue(null as any);
    const res = await exec(`{ ship(id: "NONEXISTENT") { id name } }`, api);
    assertNoInternalError(res);
    expect(singleResult(res).data?.ship).toBeNull();
  });

  it('launch(id) → null when upstream returns null', async () => {
    const api = new API() as jest.Mocked<API>;
    api.getLaunch.mockResolvedValue(null as any);
    const res = await exec(`{ launch(id: "NONEXISTENT") { id } }`, api);
    assertNoInternalError(res);
    expect(singleResult(res).data?.launch).toBeNull();
  });

  it('company → null when upstream returns null', async () => {
    const api = new API() as jest.Mocked<API>;
    api.company.mockResolvedValue(null as any);
    const res = await exec(`{ company { name ceo } }`, api);
    assertNoInternalError(res);
    expect(singleResult(res).data?.company).toBeNull();
  });

  it('roadster → null when upstream returns null', async () => {
    const api = new API() as jest.Mocked<API>;
    (api as any).getRoadster = jest.fn().mockResolvedValue(null);
    api.getRoadster?.mockResolvedValue(null as any);
    const res = await exec(`{ roadster { name speed_kph } }`, api);
    assertNoInternalError(res);
    // roadster is nullable — null is a valid response
    expect(singleResult(res).data?.roadster == null || singleResult(res).errors == null).toBe(true);
  });
});

// ── null nested objects ────────────────────────────────────────────────────────

describe('Generated Null Handling: null nested objects', () => {
  it('Launch.links → null when upstream links is null', async () => {
    const api = new API() as jest.Mocked<API>;
    api.getLaunches.mockResolvedValue([{ id: 'L1', links: null }] as any);
    const res = await exec(
      `{ launches(limit: 1) { id links { article_link video_link } } }`,
      api,
    );
    assertNoInternalError(res);
    expect(singleResult(res).data?.launches[0]?.links).toBeNull();
  });

  it('Launch.ships → null when parent.ships is null', async () => {
    const api = new API() as jest.Mocked<API>;
    api.getLaunches.mockResolvedValue([{ id: 'L1', ships: null }] as any);
    const res = await exec(
      `{ launches(limit: 1) { id ships { id } } }`,
      api,
    );
    assertNoInternalError(res);
    expect(singleResult(res).data?.launches[0]?.ships).toBeNull();
  });

  it('Launch.rocket → null rocket sub-object when upstream rocket is null string', async () => {
    const api = new API() as jest.Mocked<API>;
    api.getLaunches.mockResolvedValue([{ id: 'L1', rocket: null }] as any);
    const res = await exec(
      `{ launches(limit: 1) { id rocket { rocket_name } } }`,
      api,
    );
    assertNoInternalError(res);
    expect(singleResult(res).data?.launches[0]?.rocket).toBeNull();
  });
});

// ── pagination edge cases ─────────────────────────────────────────────────────

describe('Generated Null Handling: pagination boundaries', () => {
  it('launches(limit: 0) → []', async () => {
    const api = new API() as jest.Mocked<API>;
    api.getLaunches.mockResolvedValue([{ id: 'L1' }, { id: 'L2' }] as any);
    const res = await exec(`{ launches(limit: 0) { id } }`, api);
    assertNoInternalError(res);
    expect(singleResult(res).data?.launches).toEqual([]);
  });

  it('launches(offset: 9999) → [] when offset exceeds total', async () => {
    const api = new API() as jest.Mocked<API>;
    api.getLaunches.mockResolvedValue([{ id: 'L1' }] as any);
    const res = await exec(`{ launches(offset: 9999) { id } }`, api);
    assertNoInternalError(res);
    expect(singleResult(res).data?.launches).toEqual([]);
  });

  it('launches(limit: 100) → all items when limit > dataset size', async () => {
    const api = new API() as jest.Mocked<API>;
    api.getLaunches.mockResolvedValue([{ id: 'L1' }, { id: 'L2' }] as any);
    const res = await exec(`{ launches(limit: 100) { id } }`, api);
    assertNoInternalError(res);
    expect(singleResult(res).data?.launches).toHaveLength(2);
  });

  it('ships(limit: 0) → []', async () => {
    const api = new API() as jest.Mocked<API>;
    api.getShips.mockResolvedValue([{ ship_id: 'S1', ship_name: 'Test' }] as any);
    const res = await exec(`{ ships(limit: 0) { id } }`, api);
    assertNoInternalError(res);
    expect(singleResult(res).data?.ships).toEqual([]);
  });
});

// ── parse-service null input guards ──────────────────────────────────────────

describe('Generated Null Handling: parse-service null inputs', () => {
  it('parseShip — weight_kg and weight_lbs both null → weight_lbs resolves without error', async () => {
    const api = new API() as jest.Mocked<API>;
    api.getShips.mockResolvedValue([
      { ship_id: 'S1', ship_name: 'NullWeightShip', ship_type: 'Tug', weight_kg: null, weight_lbs: null },
    ] as any);
    const res = await exec(`{ ships { id name weight_kg weight_lbs } }`, api);
    assertNoInternalError(res);
    expect(singleResult(res).data?.ships[0]?.id).toBe('S1');
    expect(singleResult(res).data?.ships[0]?.name).toBe('NullWeightShip');
  });

  it('parseShip — weight_kg present, weight_lbs null → lbs derived from kg without error', async () => {
    const api = new API() as jest.Mocked<API>;
    api.getShips.mockResolvedValue([
      { ship_id: 'S2', ship_name: 'KgOnlyShip', weight_kg: 10000, weight_lbs: null },
    ] as any);
    const res = await exec(`{ ships { id weight_kg weight_lbs } }`, api);
    assertNoInternalError(res);
    const ship = singleResult(res).data?.ships[0];
    expect(ship?.weight_kg).toBe(10000);
    // weight_lbs should be derived: Math.round(10000 * 2.20462262) = 22046
    expect(ship?.weight_lbs).toBe(22046);
  });

  it('ships list — one null item in array — filtered without crashing', async () => {
    const api = new API() as jest.Mocked<API>;
    api.getShips.mockResolvedValue([
      null,
      { ship_id: 'S3', ship_name: 'ValidShip' },
    ] as any);
    const res = await exec(`{ ships { id name } }`, api);
    assertNoInternalError(res);
    // null entries are filtered by `data.filter(d => !!d)` in ships.ts
    const ships = singleResult(res).data?.ships;
    expect(ships).toHaveLength(1);
    expect(ships[0].id).toBe('S3');
  });
});
